Plan:
1. Copy the workbook and read cached values from the active sheet.
2. Aggregate quantities in `D4:D11` by model in `C4:C11`.
3. Write the totals for the models in `F4:F6` into the answer cells `G4:G6`.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title] if ws.title in vals.sheetnames else vals.active

def to_number(x):
    if isinstance(x, bool):
        return None
    if isinstance(x, (int, float)):
        return float(x)
    try:
        return float(str(x).strip())
    except Exception:
        return None

totals = {}
for r in range(4, 12):
    model = vws.cell(row=r, column=3).value
    qty = to_number(vws.cell(row=r, column=4).value)
    if model is None or qty is None:
        continue
    key = str(model).strip()
    totals[key] = totals.get(key, 0.0) + qty

for r in range(4, 7):
    model = vws.cell(row=r, column=6).value
    if model is None:
        ws.cell(row=r, column=7).value = None
        continue
    key = str(model).strip()
    total = totals.get(key, 0.0)
    if float(total).is_integer():
        total = int(total)
    ws.cell(row=r, column=7).value = total
    print(f"G{r} for {key}: {total}")

wb.save(OUT)
